{"query":"
        query bannerQuery ($isPreviewMode: Boolean = false) @inContext(language: EN, country: US) {
          consentManagement {
            banner {
              enabled
              position
              policyLinkText
              policyLinkUrl
              title
              text
              buttonPrefsOpenText
              buttonAcceptText
              buttonDeclineText
              regionVisibility @include(if: $isPreviewMode)
              theme {
                theme
                fontColor
                backgroundColor
                buttonFontColor
                buttonBackgroundColor
              }
              preferences {
                title
                introTitle
                introText
                buttonAcceptText
                buttonDeclineText
                buttonSaveText
                bulletPoints {
                  enabled
                  title
                  firstText
                  secondText
                  thirdText
                }
                purposes {
                  essentialName
                  essentialDesc
                  performanceName
                  performanceDesc
                  preferencesName
                  preferencesDesc
                  marketingName
                  marketingDesc
                }
              }
            }
          }
        }","variables":{"isPreviewMode":false}}

{"query":"
      query GetStorefrontCart($id: ID!) {
        cart(id: $id) {
          id
          discountCodes {
            code
            applicable
          }
          attributes {
            key
            value
          }
          lines(first: 250) {
            edges {
              node {
                attributes {
                  key
                  value
                }
                id
                cost {
                  totalAmount {
                    amount
                  }
                }
                quantity
                sellingPlanAllocation {
                  priceAdjustments {
                    price {
                      amount
                    }
                    compareAtPrice {
                      amount
                    }
                    perDeliveryPrice {
                      amount
                    }
                  }
                  sellingPlan {
                    id
                    name
                    description
                    recurringDeliveries
                  }
                }
                merchandise {
                  ... on ProductVariant {
                    id
                    price {
                      amount
                    }
                    product {
                      handle
                      id
                      tags
                      title
                      vendor
                    }
                    requiresShipping
                  }
                }
              }
            }
          }
          cost {
            totalAmount {
              amount
              currencyCode
            }
            subtotalAmount {
              amount
            }
          }
        }
      }
    ","variables":{"id":"gid://shopify/Cart/hWNHdC2vksH01BPCx3nqaonY?key=9868e0e725242b59e6ab5b2ed2c04d97"}}

